function routeMeta(name){const base=ROUTES[name]||ROUTES.dashboard,m=DATA.metadata||{};if(name==='edital')return{...base,eyebrow:`Base ${m.baseYear||m.baseEdital||''}`};if(name==='curso')return{...base,title:m.courseShortLabel||'Material de estudo',eyebrow:`${DATA.course?.length||0} aulas`};if(name==='discursiva')return{...base,title:m.writingNavLabel||'Produção textual',eyebrow:m.writingEyebrow||'Treino'};if(name==='ranking')return{...base,title:'Meu ranking',eyebrow:'Comparação BACEN 2024'};if(name==='cobertura')return{...base,title:activeContest==='bacen'?'Cobertura do curso':'Materiais do curso',eyebrow:activeContest==='bacen'?'Lacunas':'Base de estudo'};return base}
