function phraseOfDay(){if(!DATA.phrases?.length)return 'Um passo de cada vez.';const start=new Date(new Date().getFullYear(),0,0),now=new Date(),day=Math.floor((now-start)/86400000);return DATA.phrases[day%DATA.phrases.length].texto}
