  const topicRows=Object.values(topics).map(x=>({...x,accuracy:x.questions?x.correct/x.questions:0,errorRate:x.questions?x.errors/x.questions:0,score:x.errors*3+(x.questions?x.errors/x.questions:0)*10+(x.weight/Math.max(1,Number(DATA.metadata.examTotalWeight||120)))*5}));
  const recommendations=topicRows.filter(x=>x.errors>0).sort((a,b)=>b.score-a.score||b.errors-a.errors).slice(0,12);
  const mostErrors=subjectRows.filter(x=>x.questions).sort((a,b)=>b.errors-a.errors||b.errorRate-a.errorRate)[0]||null;
  const mostCorrect=subjectRows.filter(x=>x.questions).sort((a,b)=>b.correct-a.correct||b.accuracy-a.accuracy)[0]||null;
  const recent=(days)=>{const cutoff=new Date();cutoff.setHours(0,0,0,0);cutoff.setDate(cutoff.getDate()-(days-1));return state.questions.filter(q=>{const d=parseLocalDate(q.date);return d&&d>=cutoff}).reduce((a,q)=>a+Number(q.questions||0),0)};
  const totalQuestions=subjectRows.reduce((a,x)=>a+x.questions,0),totalCorrect=subjectRows.reduce((a,x)=>a+x.correct,0),totalErrors=totalQuestions-totalCorrect;
